<script setup lang="ts">
import { Delete, Plus } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import { stringify } from 'yaml'
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'

import { createHyperparameterTemplate, getHyperparameterCatalog, getHyperparameterTemplate, validateHyperparameterRaw, type BatchMode, type ParameterDefinition, type ValidationIssue } from '../api/hyperparameters'
import PageHeader from '../components/PageHeader.vue'

const route=useRoute();const router=useRouter();const catalog=ref<ParameterDefinition[]>([]);const name=ref('');const description=ref('');const epochs=ref(100);const batchMode=ref<BatchMode>('auto');const batchValue=ref<number|null>(null);const imageSize=ref(640);const extra=reactive<Record<string,unknown>>({});const selectedKey=ref('');const raw=ref('');const rawDirty=ref(false);const issues=ref<ValidationIssue[]>([]);const parsing=ref(false);const saving=ref(false);const derivedFromId=ref<string|null>(null);const applying=ref(false)
const available=computed(()=>catalog.value.filter(item=>!(item.key in extra)));const definitions=computed(()=>Object.fromEntries(catalog.value.map(item=>[item.key,item])))
function batch(){return batchMode.value==='auto'?-1:batchValue.value}
function values(){return{epochs:epochs.value,batch:batch(),imgsz:imageSize.value,...extra}}
function syncRaw(){if(rawDirty.value||applying.value)return;raw.value=stringify(values(),{lineWidth:0})}
function addParameter(){if(!selectedKey.value)return;const definition=definitions.value[selectedKey.value];extra[selectedKey.value]=definition.default;selectedKey.value='';syncRaw()}
function removeParameter(key:string){delete extra[key];syncRaw()}
watch(batchMode,(mode)=>{if(applying.value)return;batchValue.value=mode==='auto'?null:mode==='fixed'?10:0.8})
function rawInput(){rawDirty.value=true;issues.value=[]}
async function parse(){parsing.value=true;try{const result=await validateHyperparameterRaw(raw.value);issues.value=result.issues;if(!result.valid||!result.normalized)return;applying.value=true;const normalized=result.normalized;epochs.value=normalized.epochs;batchMode.value=normalized.batch_mode;batchValue.value=normalized.batch_value;imageSize.value=normalized.image_size;for(const key of Object.keys(extra))delete extra[key];Object.assign(extra,normalized.extra_parameters);raw.value=result.normalized_raw??raw.value;rawDirty.value=false;ElMessage.success('RAW 已通过校验并解析到表单。')}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'RAW 校验失败')}finally{applying.value=false;parsing.value=false}}
async function save(){if(!name.value.trim())return;saving.value=true;try{const created=await createHyperparameterTemplate({name:name.value,description:description.value,epochs:epochs.value,batch_mode:batchMode.value,batch_value:batchMode.value==='auto'?null:batchValue.value,image_size:imageSize.value,extra_parameters:{...extra},derived_from_id:derivedFromId.value});await router.push(`/hyperparameter-templates/${created.id}`)}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'模板创建失败')}finally{saving.value=false}}
watch([epochs,batchMode,batchValue,imageSize,()=>JSON.stringify(extra)],syncRaw,{immediate:true})
onMounted(async()=>{const [nextCatalog,source]=await Promise.all([getHyperparameterCatalog(),typeof route.query.from==='string'?getHyperparameterTemplate(route.query.from):Promise.resolve(null)]);catalog.value=nextCatalog.items;if(source){applying.value=true;derivedFromId.value=source.id;name.value=`${source.name} - 派生`;description.value=source.description;epochs.value=source.epochs;batchMode.value=source.batch_mode;batchValue.value=source.batch_value;imageSize.value=source.image_size;Object.assign(extra,source.extra_parameters);applying.value=false}rawDirty.value=false;syncRaw()})
</script>
<template><main class="content-page editor-page"><PageHeader :title="derivedFromId?'派生超参数模板':'新建超参数模板'" back-to="/hyperparameter-templates"><template #meta>YOLO Detect / {{ catalog.length }} 个可选参数</template><template #actions><el-button type="primary" :loading="saving" :disabled="!name.trim()||rawDirty" @click="save">创建模板</el-button></template></PageHeader><div class="editor-layout"><section class="form-pane"><el-form label-position="top"><el-form-item label="模板名称"><el-input v-model="name" maxlength="128" show-word-limit /></el-form-item><el-form-item label="描述"><el-input v-model="description" type="textarea" :rows="2" maxlength="2000" /></el-form-item><div class="core-grid"><el-form-item label="epochs"><el-input-number v-model="epochs" :min="1" :max="100000" :controls="false" /></el-form-item><el-form-item :label="`image size · ${imageSize}`"><el-slider v-model="imageSize" :min="32" :max="1280" :step="32" show-stops /></el-form-item><el-form-item label="batch size"><div class="batch-controls"><el-select v-model="batchMode"><el-option label="自动" value="auto"/><el-option label="固定数量" value="fixed"/><el-option label="显存比例" value="fraction"/></el-select><el-input-number v-model="batchValue" :class="{invisible:batchMode==='auto'}" :disabled="batchMode==='auto'" :min="batchMode==='fixed'?1:0.01" :max="batchMode==='fixed'?4096:1" :step="batchMode==='fixed'?1:0.05" :precision="batchMode==='fraction'?2:0" /></div></el-form-item></div></el-form><div class="extra-heading"><div><strong>附加超参数</strong><p>从 Detect 参数目录中按需添加。</p></div></div><div class="parameter-list"><div v-for="key in Object.keys(extra)" :key="key" class="parameter-row"><label><strong>{{ definitions[key]?.label }}</strong><code>{{ key }}</code><small v-if="definitions[key]?.minimum!=null">{{ definitions[key]?.minimum }} – {{ definitions[key]?.maximum }}</small></label><el-switch v-if="definitions[key]?.value_type==='boolean'" v-model="extra[key]"/><el-select v-else-if="key==='cache'" v-model="extra[key]"><el-option label="关闭" :value="false"/><el-option label="内存 / ram" value="ram"/><el-option label="磁盘 / disk" value="disk"/></el-select><el-select v-else-if="definitions[key]?.choices.length" v-model="extra[key]"><el-option v-for="choice in definitions[key].choices" :key="choice" :label="choice" :value="choice"/></el-select><el-input-number v-else v-model="extra[key] as number" :min="definitions[key]?.minimum??undefined" :max="definitions[key]?.maximum??undefined" :step="definitions[key]?.step" :precision="definitions[key]?.precision" :controls="definitions[key]?.controls"/><el-button text type="danger" :icon="Delete" :aria-label="`移除 ${key}`" @click="removeParameter(String(key))"/></div><el-empty v-if="!Object.keys(extra).length" :image-size="72" description="尚未添加附加参数"/><div v-if="available.length" class="parameter-add"><el-select v-model="selectedKey" filterable placeholder="选择要添加的参数"><el-option v-for="item in available" :key="item.key" :label="`${item.label} / ${item.key}`" :value="item.key" /></el-select><el-button :icon="Plus" :disabled="!selectedKey" @click="addParameter">添加参数</el-button></div></div></section><aside class="raw-pane"><header><div><span>RAW / YAML</span><strong>{{ rawDirty?'有未解析更改':'已与表单同步' }}</strong></div><el-button :loading="parsing" @click="parse">校验并解析</el-button></header><textarea v-model="raw" spellcheck="false" aria-label="RAW 超参数 YAML" @input="rawInput"/><el-alert v-if="rawDirty" title="RAW 更改尚未应用。只有全部校验通过后，左侧表单才会更新。" type="warning" :closable="false"/><ul v-if="issues.length" class="issues"><li v-for="(issue,index) in issues" :key="index"><code v-if="issue.line">L{{ issue.line }}{{ issue.key?` · ${issue.key}`:'' }}</code>{{ issue.message }}</li></ul></aside></div></main></template>
<style scoped>.editor-page{background:var(--vdw-canvas);color:var(--vdw-ink)}.editor-layout{display:grid;grid-template-columns:minmax(560px,1.2fr) minmax(380px,.8fr);gap:18px;padding:24px}.form-pane,.raw-pane{background:var(--vdw-surface-raised);border:1px solid var(--vdw-rule);border-radius:var(--vdm-radius-card);box-shadow:var(--vdm-shadow-card);padding:24px}.core-grid{display:grid;grid-template-columns:1fr 1.6fr;gap:4px 22px}.core-grid> :last-child{grid-column:1/-1}.batch-controls{display:grid;grid-template-columns:minmax(180px,1fr) minmax(180px,1fr);gap:14px}.invisible{visibility:hidden;pointer-events:none}.extra-heading,.extra-heading>div,.raw-pane>header,.raw-pane header>div{display:flex;align-items:center;justify-content:space-between;gap:10px}.extra-heading p{margin:4px 0;color:var(--vdw-muted)}.parameter-list{margin-top:14px;border-top:1px solid var(--vdw-rule)}.parameter-row{display:grid;grid-template-columns:minmax(180px,1fr) 220px 36px;gap:14px;align-items:center;padding:12px 0;border-bottom:1px solid var(--vdw-rule)}.parameter-row label{display:flex;flex-direction:column}.parameter-row small{margin-top:3px;color:var(--vdw-subtle)}.parameter-row code,.raw-pane header span{color:var(--vdw-teal);font:13px var(--vdw-mono)}.parameter-add{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;padding-top:16px}.raw-pane{display:flex;flex-direction:column;gap:14px;position:sticky;top:16px;height:calc(100vh - 130px)}.raw-pane header>div{align-items:flex-start;flex-direction:column}.raw-pane textarea{flex:1;min-height:420px;resize:none;padding:18px;border:1px solid var(--vdw-focus-rule);border-radius:var(--vdm-radius-control);background:var(--vdw-focus-canvas);color:var(--vdw-focus-ink);font:14px/1.7 var(--vdw-mono);outline:none}.raw-pane textarea:focus{box-shadow:var(--vdm-focus-ring)}.issues{margin:0;padding:12px 16px 12px 32px;background:var(--el-color-danger-light-9);color:var(--el-color-danger)}.issues code{margin-right:8px}</style>
